def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)

    # Identify the repeated frame/grid-line color. The background can also
    # occupy mostly uniform rows and columns, so prefer the candidate with
    # the fewest such lines.
    candidates = []
    for color in colors:
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.7 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.7 * h]
        if len(rows) >= 2 and len(cols) >= 2:
            candidates.append((len(rows) + len(cols), color, rows, cols))

    _, frame, frame_rows, frame_cols = min(candidates)

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Keep only frame lines that contain at least one colored marker.
    marker_rows = sorted({
        r for r in frame_rows
        if any(grid[r][c] != frame for c in frame_cols)
    })
    marker_cols = sorted({
        c for c in frame_cols
        if any(grid[r][c] != frame for r in frame_rows)
    })

    result = []
    for i in range(len(marker_rows) - 1):
        out_row = []
        for j in range(len(marker_cols) - 1):
            corners = (
                grid[marker_rows[i]][marker_cols[j]],
                grid[marker_rows[i]][marker_cols[j + 1]],
                grid[marker_rows[i + 1]][marker_cols[j]],
                grid[marker_rows[i + 1]][marker_cols[j + 1]],
            )
            value = corners[0]
            if value == frame or value == background or any(v != value for v in corners):
                value = background
            out_row.append(value)
        result.append(out_row)
    return result
